const body = items[0].json.body;
if (!body) throw new Error('No se encontró el campo body con el audio base64.');

// Elimina el prefijo data: si existe
theData = body.includes(',') ? body.split(',')[1] : body;

const buffer = Buffer.from(theData, 'base64');

return [{
  binary: {
    data: {
      data: buffer,
      mimeType: 'audio/ogg',
      fileName: 'whatsapp_audio.ogg'
    }
  },
  json: {
    info: 'Audio convertido correctamente a binario listo para analizar'
  }
}];
